import{z as i,x as n,o as A,c as s,q as e,j as l,D as a,d as B,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"主动采集下一批偏好","description":"","frontmatter":{"title":"主动采集下一批偏好","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-active-collection.md","filePath":"llm/rm-active-collection.md","lastUpdated":1791063341000}'),D={name:"llm/rm-active-collection.md"};function m(C,E,d,p,h,F){const t=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="主动采集下一批偏好" tabindex="-1">主动采集下一批偏好 <a class="header-anchor" href="#主动采集下一批偏好" aria-label="Permalink to &quot;主动采集下一批偏好&quot;">​</a></h1><div class="epigraph"><p>标注预算花在哪一对，是奖励工程里杠杆最大的单一决策：RM 已经分得对的对，再标一万次也是零信息。</p><footer>—— 不确定性采样框架见 Settles 综述 2009；偏好式主动学习见 Sadigh 等 2017；迭代采集见 Stiennon 等 2020</footer></div><p><a href="/llm/rm-variance-policy">上一课</a>把奖励的方差接进策略稳定的账；本课换到工程与评测单元，回到数据侧回答一个滚动问题：下一批标注预算花在哪。前面的课留了两条线索——<a href="/llm/rm-ood-behavior">OOD 课</a>说「分歧大的样本是下一批标注的最优原料」，<a href="/llm/annotation-agreement">一致性课</a>说「难分的对恰好是翻转率最高的对」；这两句话表面打架，本课把它们摆进同一个采集策略里。<a href="/llm/rft-data-loop">拒绝采样数据循环</a>在主干讲过策略侧的数据循环，本课只管标注预算这一段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机采集新策略样本去标注，预算的大头会浪费在两类对上：RM 已经分得很对的（梯度趋零，标了不长本事），以及人自己都分不清的（上一致性课的「真模糊」档，标了注入噪声）。采集的目标函数因此不是「多标」，而是单位标注成本换来的 RM 改进最大。InstructGPT 与 Stiennon 等 2020 的迭代流程已经隐含了这个逻辑：每轮用新策略的样本重采比较，因为旧分布上的对随着策略移动不断失效；本课把「挑哪些」从隐式变成显式算法。</p><p><span class="marginnote">「主动采集」就是机器学习里的「主动学习」：不是随机发卷子，而是模型先挑出自己最拿不准的题去问老师。直觉是——会做的题刷一万遍分数也不涨，涨分的永远藏在不会做的那批题里，标注预算就该花在那里。</span></p><h3 id="选对的三类信号" tabindex="-1">选对的三类信号 <a class="header-anchor" href="#选对的三类信号" aria-label="Permalink to &quot;选对的三类信号&quot;">​</a></h3><p>不确定性信号：RM 对某对越拿不准，标它越可能改边界。两个口径——分数贴近判别边界（\\(|r_w-r_l|\\) 小，BT 损失的梯度 \\(\\sigma(-\\Delta)\\) 在 \\(\\Delta=0\\) 处最大），以及集成分歧 \\(\\hat\\sigma\\) 大（<a href="/llm/rm-ensembles">RM 集成</a>的 epistemic 信号，上一课刚讲过它在支撑外的抬升）。覆盖信号：只挑不确定的会聚成一堆同质怪样本，要对提示嵌入做多样性约束（聚类的核采样思路）。价值信号：不确定 × 流量重要度——线上高频提示域的不确定对，优先级高于猎奇提示。</p>',8)),(A(),l(o,null,{default:a(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E6%96%B0%E7%AD%96%E7%95%A5%E6%A0%B7%E6%9C%AC%E6%B1%A0%22%5D%20--%3E%20SC%5B%22RM%20%E6%89%93%E5%88%86%E4%B8%8E%E9%9B%86%E6%88%90%E5%88%86%E6%AD%A7%22%5D%0A%20%20SC%20--%3E%20UNC%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%EF%BC%9A%CE%94r%20%E5%B0%8F%E6%88%96%E5%88%86%E6%AD%A7%E5%A4%A7%22%5D%0A%20%20UNC%20--%3E%20FILTER%5B%22%E5%89%94%E9%99%A4%E4%B8%8E%E4%BA%BA%E7%B1%BB%E4%B8%80%E8%87%B4%E7%8E%87%E5%B7%AE%E7%9A%84%E5%9F%9F%22%5D%0A%20%20FILTER%20--%3E%20DIV%5B%22%E5%A4%9A%E6%A0%B7%E6%80%A7%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%81%9A%E7%B1%BB%E6%A0%B8%E9%87%87%22%5D%0A%20%20DIV%20--%3E%20BUDGET%5B%22%E6%8C%89%E6%B5%81%E9%87%8F%E9%87%8D%E8%A6%81%E5%BA%A6%E6%8E%92%E5%BA%8F%EF%BC%8C%E5%88%87%E9%A2%84%E7%AE%97%22%5D%0A%20%20BUDGET%20--%3E%20LABEL%5B%22%E4%BA%BA%E5%B7%A5%E6%A0%87%E6%B3%A8%22%5D%0A%20%20LABEL%20--%3E%20RETRAIN%5B%22%E9%87%8D%E8%AE%AD%20RM%20%2B%20%E5%88%86%E5%9F%9F%E9%AA%8C%E6%94%B6%22%5D%0A%20%20RETRAIN%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%EF%BC%9A%E7%AD%96%E7%95%A5%E6%9B%B4%E6%96%B0%E5%90%8E%E9%87%8D%E9%87%87%22%5D%0A%20%20NEXT%20--%3E%20POOL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一轮采集的流水线：新策略 rollout 出候选池；当前 RM（最好带集成）打分；按 \\(|\\Delta r|\\) 与 \\(\\hat\\sigma\\) 排出不确定带；先剔除高危——上一致性课分域一致率低的域里，「不确定」大概率是「人类也不确定」，标了白标，这类对转仲裁或丢弃而不是进池；再过多样性约束防止样本塌缩到少数提示；按流量分布加权后切预算送标；标完重训、分域验收，进下一轮。节奏对齐策略迭代：策略每前进一段，旧比较对就贬值一截，采集是滚动预算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不确定性采样为什么有效：BT 损失对单对的梯度模是 \\(\\sigma(-(r_w-r_l))\\)，在 \\(\\Delta=0\\) 处最大、在两端指数衰减——分得对的对几乎不产生梯度，挑 \\(\\Delta\\approx 0\\) 的对等于把预算花在梯度最大的地方。集成分歧补的是另一半：\\(|\\Delta r|\\) 小可能是「真接近」也可能是「RM 瞎猜」，分歧大标记后者，而后者才需要人。这与主动学习的一般原理一致（Settles 2009）：查询分类器最不确信的样本，期望的假设空间收缩最大。两句话打架的化解也在这里：OOD 课说的「分歧大要标」针对<strong>人能判而 RM 不能</strong>的区域；一致性课警告的是<strong>人也不能判</strong>的区域——所以采集流水线必须在不确定性信号后接人类一致率过滤器，顺序不能反。</p><p><span class="marginnote">数字实例看梯度的悬殊：BT 损失的梯度是 \\(\\sigma(-\\Delta)\\)。取 \\(\\Delta=0\\)（RM 五五开），梯度 0.5，最大；取 \\(\\Delta=4\\)（比较确定），约 0.018；取 \\(\\Delta=8\\)，约 0.0003——差出三个数量级。同一份预算，标在 \\(\\Delta\\approx 0\\) 的对上，买到的是近千倍的训练信号。</span></p>',5)),(A(),l(o,null,{default:a(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E4%B8%80%E5%AF%B9%E6%A0%B7%E6%9C%AC%EF%BC%9A%E5%88%86%E5%B7%AE%20%CE%94r%20%3D%20r_w%20%E2%88%92%20r_l%22%5D%20--%3E%20A%7B%22%CE%94r%20%E8%90%BD%E5%9C%A8%E5%93%AA%EF%BC%9F%22%7D%0A%20%20A%20--%3E%7C%22%E7%BA%A6%E7%AD%89%E4%BA%8E%200%EF%BC%9ARM%20%E6%8B%BF%E4%B8%8D%E5%87%86%22%7C%20G1%5B%22BT%20%E6%A2%AF%E5%BA%A6%E6%9C%80%E5%A4%A7%EF%BC%9A%E6%A0%87%E5%AE%83%E6%9C%80%E5%88%92%E7%AE%97%22%5D%0A%20%20A%20--%3E%7C%22%E5%BE%88%E5%A4%A7%EF%BC%9ARM%20%E5%BE%88%E7%A1%AE%E5%AE%9A%22%7C%20G2%5B%22%E6%A2%AF%E5%BA%A6%E8%B6%8B%E9%9B%B6%EF%BC%9A%E6%A0%87%E4%BA%86%E4%B8%8D%E9%95%BF%E6%9C%AC%E4%BA%8B%22%5D%0A%20%20U%5B%22%E4%BD%86%20%CE%94r%20%E5%B0%8F%E4%B9%9F%E5%8F%AF%E8%83%BD%E6%98%AF%20RM%20%E7%9E%8E%E7%8C%9C%22%5D%20--%3E%20E%7B%22%E9%9B%86%E6%88%90%E5%88%86%E6%AD%A7%20%CF%83%CC%82%20%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%22%E5%A4%A7%22%7C%20H1%5B%22RM%20%E7%9C%9F%E4%B8%8D%E4%BC%9A%EF%BC%9A%E8%BF%9B%E6%A0%87%E6%B3%A8%E6%B1%A0%E9%97%AE%E4%BA%BA%22%5D%0A%20%20E%20--%3E%7C%22%E5%B0%8F%22%7C%20H2%5B%22%E5%8F%AA%E6%98%AF%E7%9C%9F%E6%8E%A5%E8%BF%91%EF%BC%9A%E5%8F%AF%E8%B7%B3%E8%BF%87%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">自选偏差是主动采集的固有税：按当前 RM 的不确定性挑对，训练分布逐步偏向 RM 的失败区域，全局准确率会因此「显得」下降。对账口径：验收永远在固定的随机抽样持有集上做，主动采集的对只进训练，不进验证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>主动采集不是越多轮越好：每轮采集都在旧 RM 的定义域附近找事，长循环后数据集体积越来越偏向边界带，支撑中心的「常识对」占比下降，RM 的基础判断反而可能松动——轮间要掺入按分布随机抽的对做打底。不确定性信号还有被利用的一面：策略若学会待在 RM 犹豫的区域，会同时压低采集效率与优化信号，这与 <a href="/llm/rm-ood-behavior">OOD 课</a>「监测量变成目标就失效」是同一条递归。最后，预算分配离不开成本口径：不同域的标注单价不同（安全域要资深标注员），单位「改进/元」的排序才是真实的优先级，纯按信息量排的采集计划在预算会上活不过第二轮。</p><p><span class="marginnote">常见误区：初学者容易以为「不确定的样本多多益善」，一轮全标边界带——结果训练分布整体偏向 RM 的失败区，支撑中心的「常识对」越来越少，RM 的基础判断反而松动。正确做法是每轮掺入按分布随机抽的对做打底，别让边界带吃掉整个菜单。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>采集目标函数是单位标注成本的 RM 改进：随机采集的大头花在零信息对上。</li><li>选对信号两层：\\(|\\Delta r|\\) 小与 \\(\\hat\\sigma\\) 大标出「RM 不确定」，人类一致率过滤掉「人也不确定」。</li><li>多样性约束与流量加权防样本塌缩；预算按「改进/元」排序。</li><li>验收只在固定随机持有集上做，自选偏差不进验证口径。</li><li>出处：Settles 2009 综述；Sadigh 等 2017；Stiennon 等 2020 的迭代采集流程。</li></ul>',6))])}const R=i(D,[["render",m]]);export{c as __pageData,R as default};
